def merge(base, over):
    out = {}
    for k, v in base.items():
        if isinstance(v, dict): out[k] = merge(v, over.get(k, {}) if isinstance(over.get(k, {}), dict) else {})
        else: out[k] = over.get(k, v)   # placeholder = English text until translated
    return out
for name, data in (("en", en), ("bn", merge(en, bn))):
    json.dump(data, open(f"src/locales/{name}.json", "w", encoding="utf-8"), ensure_ascii=False, indent=2)
